            if($id){$sql='UPDATE news SET title=?,slug=?,excerpt=?,content=?,category=?,status=?,published_at=?'.($image?',image_path=?':'').' WHERE id=?';if($image)$values[]=$image;$values[]=$id;db()->prepare($sql)->execute($values);audit('update','news',$id);}else{$values[]=$image;db()->prepare('INSERT INTO news(title,slug,excerpt,content,category,status,published_at,image_path) VALUES(?,?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();audit('create','news',$id);}go('news','News item saved.');
        }
        if($action==='save_event'){
            ensure_event_images_table();ensure_event_tags_column();ensure_booking_schema();$allowedImages=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$id=(int)($_POST['id']??0);$image=upload_file('image',$allowedImages,'images');$gallery=upload_files('gallery_images',$allowedImages,'images');if(!$image&&$gallery&&!$id)$image=$gallery[0];$slug=slugify($_POST['slug']?:$_POST['title']);$tags=trim(preg_replace('/\s*[,#]\s*/',', ',trim((string)($_POST['tags']??''),' #,')));$pricing=($_POST['pricing_type']??'free')==='paid'?'paid':'free';$values=[trim($_POST['title']),$slug,trim($_POST['summary']),trim($_POST['description']),$tags,trim($_POST['venue']),str_replace('T',' ',$_POST['starts_at']),$_POST['ends_at']?str_replace('T',' ',$_POST['ends_at']):null,trim($_POST['registration_url']),isset($_POST['booking_enabled'])?1:0,$pricing,$pricing==='paid'?(float)($_POST['member_price']??0):0,$pricing==='paid'?(float)($_POST['non_member_price']??0):0,'LKR',($_POST['capacity']??'')!==''?(int)$_POST['capacity']:null,isset($_POST['bank_transfer_enabled'])?1:0,trim((string)($_POST['bank_details']??'')),isset($_POST['featured'])?1:0,$_POST['status']];
            if($id){$sql='UPDATE events SET title=?,slug=?,summary=?,description=?,tags=?,venue=?,starts_at=?,ends_at=?,registration_url=?,booking_enabled=?,pricing_type=?,member_price=?,non_member_price=?,currency=?,capacity=?,bank_transfer_enabled=?,bank_details=?,featured=?,status=?'.($image?',image_path=?':'').' WHERE id=?';if($image)$values[]=$image;$values[]=$id;db()->prepare($sql)->execute($values);audit('update','event',$id);}else{$values[]=$image;db()->prepare('INSERT INTO events(title,slug,summary,description,tags,venue,starts_at,ends_at,registration_url,booking_enabled,pricing_type,member_price,non_member_price,currency,capacity,bank_transfer_enabled,bank_details,featured,status,image_path) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();audit('create','event',$id);}
            if($gallery){$order=(int)db()->query('SELECT COALESCE(MAX(sort_order),-1)+1 FROM event_images WHERE event_id='.(int)$id)->fetchColumn();$galleryStmt=db()->prepare('INSERT INTO event_images(event_id,image_path,sort_order) VALUES(?,?,?)');foreach($gallery as $path)$galleryStmt->execute([$id,$path,$order++]);}go('events','Event saved.');
        }
