            ensure_event_images_table();$imageId=(int)($_POST['image_id']??0);$eventId=(int)($_POST['event_id']??0);$stmt=db()->prepare('DELETE FROM event_images WHERE id=? AND event_id=?');$stmt->execute([$imageId,$eventId]);audit('delete','event_image',$imageId,['event_id'=>$eventId]);go('events','Gallery image removed.');
