        if($action==='set_booking_status'){ensure_booking_schema();$id=(int)$_POST['id'];$valid=['pending_verification','confirmed','rejected','cancelled'];$status=in_array($_POST['status']??'',$valid,true)?$_POST['status']:'pending_verification';$notes=trim((string)($_POST['admin_notes']??''));$currentStmt=db()->prepare('SELECT status FROM event_bookings WHERE id=?');$currentStmt->execute([$id]);$previous=(string)$currentStmt->fetchColumn();$verified=in_array($status,['confirmed','rejected'],true);db()->prepare('UPDATE event_bookings SET status=?,admin_notes=?,verified_by=?,verified_at=? WHERE id=?')->execute([$status,$notes,$verified?(int)admin_user()['id']:null,$verified?date('Y-m-d H:i:s'):null,$id]);$message='Booking updated.';if($status==='confirmed'){$tickets=issue_tickets_for_booking($id);$mailed=$previous!=='confirmed'?send_ticket_email($id):null;$message=count($tickets).' e-ticket'.(count($tickets)===1?'':'s').' ready'.($mailed===true?' and emailed.':($mailed===false?'; email delivery failed, so please share the ticket links manually.':'.'));}elseif(in_array($status,['rejected','cancelled'],true)){db()->prepare("UPDATE event_tickets SET status='void' WHERE booking_id=?")->execute([$id]);}audit('status','event_booking',$id,['status'=>$status]);go('bookings',$message);}
