" value="<?=e(isset($item['capacity'])?(string)$item['capacity']:'')?>" placeholder="Unlimited"></label><label>Member price (LKR)<input type="number" min="0" step="0.01" name="member_price" value="<?=e((string)($item['member_price']??0))?>"></label><label>Non-member price (LKR)<input type="number" min="0" step="0.01" name="non_member_price" value="<?=e((string)($item['non_member_price']??0))?>"></label><label class="check full"><input type="checkbox" name="bank_transfer_enabled" <?=!isset($item['bank_transfer_enabled'])||!empty($item['bank_transfer_enabled'])?'checked':''?>> Accept bank transfer receipts</label><label class="full">Bank transfer instructions<textarea name="bank_details" rows="4" placeholder="Bank, branch, account name and account number. These details appear during checkout."><?=e($item['bank_details']??'')?></textarea></label></div></div><label class="full">Summary<textarea name="summary" rows="3"><?=e($item['summary']??'')?></textarea></label><label class="full">Description<textarea name="description" rows="8"><?=e($item['description']??'')?></textarea></label><label class="full">SEO tags<input name="tags" value="<?=e($item['tags']??'')?>" placeholder="interior design, workshop, Sri Lanka, professional development"><span class="field-help">Separate tags with commas. The website will display them with # symbols.</span></label><label>Main event image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><span class="field-help">Used as the large cover image.</span></label><label>Gallery images<input type="file" name="gallery_images[]" accept="image/jpeg,image/png,image/webp" multiple><span class="field-help">Select up to 12 images at once.</span></label><label class="check"><input type="checkbox" name="featured" <?=!empty($item['featured'])?'checked':''?>> Featured event</label><button>Save event</button></form><?php if($gallery):?><div class="admin-gallery"><h3>Current gallery</h3><div><?php foreach($gallery as $galleryImage):?><figure><img src="<?=e(public_url($galleryImage['image_path']))?>" alt=""><form method="post" onsubmit="return confirm('Remove this gallery image?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_event_image"><input type="hidden" name="event_id" value="<?=$editId?>"><input type="hidden" name="image_id" value="<?=$galleryImage['id']?>"><button>Remove</button></form></figure><?php endforeach?></div></div><?php endif?></section><?=render_table('events',rows('events','starts_at DESC'),['title'=>'Title','venue'=>'Venue','starts_at'=>'Start','booking_enabled'=>'Booking','status'=>'Status'])?>
<?php elseif($section==='bookings'):ensure_booking_schema();$bookings=db()->query('SELECT b.*,e.title event_title FROM event_bookings b JOIN events e ON e.id=b.event_id ORDER BY b.created_at DESC LIMIT 250')->fetchAll();?><section class="panel booking-list"><div class="panel-heading"><div><h2>Event bookings</h2><p>Open each bank receipt, confirm that the amount reached the account, then approve or reject the booking.</p></div><span class="status-badge pending"><?=db()->query("SELECT COUNT(*) FROM event_bookings WHERE status='pending_verification'")->fetchColumn()?> awaiting verification</span></div><?php if(!$bookings):?><p>No bookings have been received yet.</p><?php endif?><?php foreach($bookings as $booking):$participantStmt=db()->prepare('SELECT p.*,t.ticket_number,t.token,t.status ticket_status FROM event_booking_participants p LEFT JOIN event_tickets t ON t.participant_id=p.id WHERE p.booking_id=? ORDER BY p.id');$participantStmt->execute([$booking['id']]);$participants=$participantStmt->fetchAll();?><article class="booking-record"><div class="booking-record-head"><div><span class="booking-reference"><?=e($booking['reference'])?></span><h3><?=e($booking['event_title'])?></h3><p><?=e($booking['purchaser_name'])?> · <a href="mailto:<?=e($booking['purchaser_email'])?>"><?=e($booking['purchaser_email'])?></a> · <?=e($booking['purchaser_phone'])?></p></div><span class="status-badge <?=e($booking['status'])?>"><?=e(str_replace('_',' ',$booking['status']))?></span></div><div class="booking-summary"><span><b><?=$booking['seats']?></b> seat<?=((int)$booking['seats']===1?'':'s')?></span><span><b><?=e($booking['currency'])?> <?=number_format((float)$booking['subtotal'],2)?></b> total</span><span><b><?=e(str_replace('_',' ',$booking['payment_method']))?></b> payment</span><span><b><?=e($booking['created_at'])?></b> submitted</span></div><details><summary>View participants</summary><div class="participant-list"><?php foreach($participants as $participant):?><p><b><?=e($participant['name'])?></b><span><?=e($participant['email'])?> · <?=e(str_replace('_',' ',$participant['attendee_type']))?><?=!empty($participant['membership_number'])?' · Member '.e($participant['membership_number']):''?><?=!empty($participant['nic'])?' · NIC '.e($participant['nic']):''?> · <?=e($booking['currency'])?> <?=number_format((float)$participant['unit_price'],2)?></span><?php if(!empty($participant['token'])):?><a class="ticket-link" href="<?=e(ticket_url($participant['token']))?>" target="_blank" rel="noopener">Open e-ticket</a><?php endif?></p><?php endforeach?></div></details><form method="post" class="booking-review-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="set_booking_status"><input type="hidden" name="id" value="<?=$booking['id']?>"><?php if($booking['receipt_path']):?><a class="receipt-link" href="?receipt=<?=$booking['id']?>" target="_blank">Open bank receipt PDF ↗</a><?php else:?><span class="receipt-missing"><?=$booking['payment_method']==='free'?'Free booking — no receipt required':'No receipt uploaded'?></span><?php endif?><label>Verification notes<input name="admin_notes" value="<?=e($booking['admin_notes']??'')?>" placeholder="Optional internal note"></label><label>Status<select name="status"><?php foreach(['pending_verification','confirmed','rejected','cancelled'] as $status):?><option value="<?=$status?>" <?=$status===$booking['status']?'selected':''?>><?=e(str_replace('_',' ',$status))?></option><?php endforeach?></select></label><button>Save verification</button><?php if($booking['status']==='confirmed'):?><button class="secondary" name="action" value="resend_tickets">Resend e-tickets</button><?php endif?></form></article><?php endforeach?></section>
<?php elseif($section==='ticket-validation'):ensure_booking_schema();?><section class="panel validator-launch"><span class="eyebrow">Entrance desk</span><h2>Validate an e-ticket</h2><p>Scan the QR code with this device, or enter the unique ticket number printed on the ticket.</p><form action="validate.php" method="get" class="ticket-search"><label>Ticket number<input name="ticket" placeholder="SLIID-26-TXXXXXXXX" required autocomplete="off"></label><button>Validate ticket</button></form><a class="validator-open" href="validate.php">Open full entrance validator</a></section>
